package com.ruoyi.business.ai.capability.project;
import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import com.ruoyi.business.ai.capability.*;import com.ruoyi.business.service.IBusinessProjectService;import static com.ruoyi.business.ai.capability.AiCapabilityInputs.*;
@Component public class RemoveProjectTaskCapability implements AiConfirmableCapability{private final IBusinessProjectService service;@Autowired public RemoveProjectTaskCapability(IBusinessProjectService s){service=s;}public String code(){return "project.task.remove";}public String description(){return "停用一项一次性任务并保留历史记录。先读取项目详情取得真实taskId；有子任务时业务服务会拒绝。";}public String requiredPermission(){return "business:project:task";}public Map<String,Object> inputSchema(){Map<String,Object>s=AiSchemas.object();AiSchemas.property(s,"projectId","number","项目ID");AiSchemas.property(s,"taskId","number","任务ID");AiSchemas.property(s,"taskName","string","任务名称，仅用于确认展示");return AiSchemas.required(s,"projectId","taskId");}public String confirmationSummary(AiCapabilityInvocation i,Map<String,Object>in){return "停用一次性任务“"+(text(in.get("taskName")).isEmpty()?"ID "+number(in.get("taskId")):text(in.get("taskName")))+"”，历史数据继续保留";}public Map<String,Object> executeConfirmed(AiCapabilityInvocation i,Map<String,Object>in){service.deleteTask(number(in.get("projectId")),number(in.get("taskId")),i.getActor().getUserId(),i.getActor().getUserName(),true);Map<String,Object>r=new LinkedHashMap<String,Object>();r.put("projectId",number(in.get("projectId")));r.put("taskId",number(in.get("taskId")));r.put("status","RETIRED");return r;}}
